' AS lista_remessas;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 2. Separação, validação e normalização da lista
-- MAGIC
-- MAGIC A chave auxiliar remove espaços, eventual `.0` e zeros à esquerda. O valor original é preservado.

-- COMMAND ----------

CREATE OR REPLACE TEMP VIEW vl06if_linhas_coladas AS
SELECT
    ROW_NUMBER() OVER (ORDER BY MONOTONICALLY_INCREASING_ID()) AS numero_linha,
    TRIM(valor) AS valor_original
FROM vl06if_texto_sap
LATERAL VIEW EXPLODE(
    SPLIT(REPLACE(lista_remessas, CHR(13), ''), CHR(10))
) linhas AS valor;

CREATE OR REPLACE TEMP VIEW vl06if_remessas_sap AS
SELECT DISTINCT
    valor_original AS num_remessa_sap,
    COALESCE(
        NULLIF(
            REGEXP_REPLACE(
                REGEXP_REPLACE(valor_original, '\\.0+$', ''),
                '^0+',
                ''
            ),
            ''
        ),
        '0'
    ) AS chave_remessa
FROM vl06if_linhas_coladas
WHERE valor_original IS NOT NULL
  AND valor_original <> ''
  AND LOWER(valor_original) NOT IN ('num_remessa', 'remessa')
  AND valor_original RLIKE '^[0-9]+(\\.0+)?$';

CREATE OR REPLACE TEMP VIEW vl06if_linhas_rejeitadas AS
SELECT numero_linha, valor_original
FROM vl06if_linhas_coladas
WHERE valor_original IS NOT NULL
  AND valor_original <> ''
  AND LOWER(valor_original) NOT IN ('num_remessa', 'remessa')
  AND NOT valor_original RLIKE '^[0-9]+(\\.0+)?$';

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 3. Controle da lista de entrada
-- MAGIC
-- MAGIC Resultado de referência: 5.331 remessas válidas distintas e nenhuma linha rejeitada.

-- COMMAND ----------

SELECT
    (SELECT COUNT(*) FROM vl06if_linhas_coladas) AS linhas_lidas_do_texto,
    (SELECT COUNT(*) FROM vl06if_remessas_sap) AS remessas_validas_distintas,
    (SELECT COUNT(*) FROM vl06if_linhas_rejeitadas) AS linhas_rejeitadas;

-- COMMAND ----------

SELECT *
FROM vl06if_linhas_rejeitadas
ORDER BY numero_linha;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 4. Recorte do Datalake
-- MAGIC
-- MAGIC A view temporária contém somente as remessas da lista SAP e preserva as 41 colunas originais, além da chave normalizada.

-- COMMAND ----------

CREATE OR REPLACE TEMP VIEW vl06if_dl AS
WITH dl_normalizado AS (
    SELECT
        dl.*,
        COALESCE(
            NULLIF(
                REGEXP_REPLACE(
                    REGEXP_REPLACE(
                        TRIM(CAST(dl.num_remessa AS STRING)),
                        '\\.0+$',
                        ''
                    ),
                    '^0+',
                    ''
                ),
                ''
            ),
            '0'
        ) AS chave_remessa
    FROM dev_procurement.corp_curated.vw_ds_log_monitor_remessas dl
)
SELECT dl.*
FROM dl_normalizado dl
INNER JOIN vl06if_remessas_sap sap
    ON dl.chave_remessa = sap.chave_remessa;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 5. Cobertura de registros
-- MAGIC
-- MAGIC Mede remessas encontradas, ausentes, linhas retornadas e repetição de chave no recorte.

-- COMMAND ----------

WITH dl_agrupado AS (
    SELECT chave_remessa, COUNT(*) AS qtd_linhas
    FROM vl06if_dl
    GROUP BY chave_remessa
)
SELECT
    COUNT(*) AS remessas_sap,
    COUNT_IF(dl.chave_remessa IS NOT NULL) AS remessas_encontradas,
    COUNT_IF(dl.chave_remessa IS NULL) AS remessas_ausentes,
    SUM(COALESCE(dl.qtd_linhas, 0)) AS linhas_datalake,
    COUNT_IF(COALESCE(dl.qtd_linhas, 0) > 1) AS remessas_repetidas_dl,
    MAX(COALESCE(dl.qtd_linhas, 0)) AS max_linhas_por_remessa_dl,
    ROUND(100.0 * COUNT_IF(dl.chave_remessa IS NOT NULL) / COUNT(*), 2)
        AS cobertura_percentual
FROM vl06if_remessas_sap sap
LEFT JOIN dl_agrupado dl
    ON sap.chave_remessa = dl.chave_remessa;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 6. Remessas ausentes
-- MAGIC
-- MAGIC A primeira consulta cria a lista. A segunda retorna todas as ausentes. A terceira desafia as ausências por comparação direta da chave bruta.

-- COMMAND ----------

CREATE OR REPLACE TEMP VIEW vl06if_remessas_ausentes AS
SELECT sap.num_remessa_sap, sap.chave_remessa
FROM vl06if_remessas_sap sap
LEFT ANTI JOIN vl06if_dl dl
    ON sap.chave_remessa = dl.chave_remessa;

SELECT *
FROM vl06if_remessas_ausentes
ORDER BY num_remessa_sap;

-- COMMAND ----------

SELECT
    aus.num_remessa_sap,
    dl.num_remessa AS num_remessa_dl,
    CASE
        WHEN dl.num_remessa IS NULL THEN 'AUSENTE_MESMO_NA_COMPARACAO_DIRETA'
        ELSE 'ENCONTRADA_NA_COMPARACAO_DIRETA'
    END AS resultado_teste_direto
FROM vl06if_remessas_ausentes aus
LEFT JOIN dev_procurement.corp_curated.vw_ds_log_monitor_remessas dl
    ON TRIM(CAST(dl.num_remessa AS STRING)) = TRIM(aus.num_remessa_sap)
ORDER BY aus.num_remessa_sap;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 7. Duplicidades e granularidade
-- MAGIC
-- MAGIC Chave repetida não é automaticamente duplicidade real. Se houver resultado, inspecione as linhas completas.

-- COMMAND ----------

SELECT
    num_remessa,
    COUNT(*) AS qtd_linhas
FROM vl06if_dl
GROUP BY num_remessa
HAVING COUNT(*) > 1
ORDER BY qtd_linhas DESC, num_remessa;

-- COMMAND ----------

SELECT
    COUNT(*) AS linhas_dl,
    COUNT(DISTINCT chave_remessa) AS remessas_distintas_dl,
    ROUND(COUNT(*) * 1.0 / COUNT(DISTINCT chave_remessa), 4)
        AS linhas_por_remessa,
    SUM(COALESCE(qt_itens_relevantes, 0)) AS itens_relevantes_informados,
    SUM(GREATEST(COALESCE(qt_itens_relevantes, 0) - 1, 0))
        AS itens_adicionais_nao_representados_como_linha
FROM vl06if_dl;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 8. Preenchimento das 41 colunas
-- MAGIC
-- MAGIC Retorna uma linha por campo, com nulos, preenchidos e percentual de preenchimento no recorte.

-- COMMAND ----------

WITH base AS (
    SELECT * FROM vl06if_dl
), perfil AS (
    SELECT STACK(
        41,
        'cod_centro', COUNT_IF(cod_centro IS NULL), COUNT_IF(cod_centro IS NOT NULL),
        'num_remessa', COUNT_IF(num_remessa IS NULL), COUNT_IF(num_remessa IS NOT NULL),
        'cod_material', COUNT_IF(cod_material IS NULL), COUNT_IF(cod_material IS NOT NULL),
        'num_item_remessa', COUNT_IF(num_item_remessa IS NULL), COUNT_IF(num_item_remessa IS NOT NULL),
        'nm_material_cliente', COUNT_IF(nm_material_cliente IS NULL), COUNT_IF(nm_material_cliente IS NOT NULL),
        'dt_criacao', COUNT_IF(dt_criacao IS NULL), COUNT_IF(dt_criacao IS NOT NULL),
        'cod_fornecedor', COUNT_IF(cod_fornecedor IS NULL), COUNT_IF(cod_fornecedor IS NOT NULL),
        'nm_fornecedor', COUNT_IF(nm_fornecedor IS NULL), COUNT_IF(nm_fornecedor IS NOT NULL),
        'cod_deposito', COUNT_IF(cod_deposito IS NULL), COUNT_IF(cod_deposito IS NOT NULL),
        'sg_unidade_medida_basica', COUNT_IF(sg_unidade_medida_basica IS NULL), COUNT_IF(sg_unidade_medida_basica IS NOT NULL),
        'qt_fornecida_fato_umv', COUNT_IF(qt_fornecida_fato_umv IS NULL), COUNT_IF(qt_fornecida_fato_umv IS NOT NULL),
        'num_pedido_compra', COUNT_IF(num_pedido_compra IS NULL), COUNT_IF(num_pedido_compra IS NOT NULL),
        'nm_inverted', COUNT_IF(nm_inverted IS NULL), COUNT_IF(nm_inverted IS NOT NULL),
        'qt_total_volumes_remessa', COUNT_IF(qt_total_volumes_remessa IS NULL), COUNT_IF(qt_total_volumes_remessa IS NOT NULL),
        'qt_itens_relevantes', COUNT_IF(qt_itens_relevantes IS NULL), COUNT_IF(qt_itens_relevantes IS NOT NULL),
        'cod_local_expedicao_ponto_recebimento', COUNT_IF(cod_local_expedicao_ponto_recebimento IS NULL), COUNT_IF(cod_local_expedicao_ponto_recebimento IS NOT NULL),
        'num_conhecimento_transporte', COUNT_IF(num_conhecimento_transporte IS NULL), COUNT_IF(num_conhecimento_transporte IS NOT NULL),
        'qt_peso_bruto_total', COUNT_IF(qt_peso_bruto_total IS NULL), COUNT_IF(qt_peso_bruto_total IS NOT NULL),
        'st_verificacao_credito_global', COUNT_IF(st_verificacao_credito_global IS NULL), COUNT_IF(st_verificacao_credito_global IS NOT NULL),
        'ind_correcao_re_avancada', COUNT_IF(ind_correcao_re_avancada IS NULL), COUNT_IF(ind_correcao_re_avancada IS NOT NULL),
        'qt_contador', COUNT_IF(qt_contador IS NULL), COUNT_IF(qt_contador IS NOT NULL),
        'ind_item_devolucao', COUNT_IF(ind_item_devolucao IS NULL), COUNT_IF(ind_item_devolucao IS NOT NULL),
        'tp_remessa', COUNT_IF(tp_remessa IS NULL), COUNT_IF(tp_remessa IS NOT NULL),
        'tp_ctg_item_remessa', COUNT_IF(tp_ctg_item_remessa IS NULL), COUNT_IF(tp_ctg_item_remessa IS NOT NULL),
        'tp_movimento_administracao_estoques', COUNT_IF(tp_movimento_administracao_estoques IS NULL), COUNT_IF(tp_movimento_administracao_estoques IS NOT NULL),
        'st_movimento_mercadorias_item', COUNT_IF(st_movimento_mercadorias_item IS NULL), COUNT_IF(st_movimento_mercadorias_item IS NOT NULL),
        'dt_remessa', COUNT_IF(dt_remessa IS NULL), COUNT_IF(dt_remessa IS NOT NULL),
        'dt_movimentacao_mercadoria_real', COUNT_IF(dt_movimentacao_mercadoria_real IS NULL), COUNT_IF(dt_movimentacao_mercadoria_real IS NOT NULL),
        'dt_planejada_movimento_mercadoria', COUNT_IF(dt_planejada_movimento_mercadoria IS NULL), COUNT_IF(dt_planejada_movimento_mercadoria IS NOT NULL),
        'dt_disponibilizacao_material', COUNT_IF(dt_disponibilizacao_material IS NULL), COUNT_IF(dt_disponibilizacao_material IS NOT NULL),
        'num_item_pedido_compra', COUNT_IF(num_item_pedido_compra IS NULL), COUNT_IF(num_item_pedido_compra IS NOT NULL),
        'num_referencia', COUNT_IF(num_referencia IS NULL), COUNT_IF(num_referencia IS NOT NULL),
        'st_movimento_mercadorias_todos_itens', COUNT_IF(st_movimento_mercadorias_todos_itens IS NULL), COUNT_IF(st_movimento_mercadorias_todos_itens IS NOT NULL),
        'cod_zonas_disponibilizacao_sistema_deposito', COUNT_IF(cod_zonas_disponibilizacao_sistema_deposito IS NULL), COUNT_IF(cod_zonas_disponibilizacao_sistema_deposito IS NOT NULL),
        'cod_organizacao_vendas', COUNT_IF(cod_organizacao_vendas IS NULL), COUNT_IF(cod_organizacao_vendas IS NOT NULL),
        'cod_canal_distribuicao', COUNT_IF(cod_canal_distribuicao IS NULL), COUNT_IF(cod_canal_distribuicao IS NOT NULL),
        'cod_setor_atividade_organizacao', COUNT_IF(cod_setor_atividade_organizacao IS NULL), COUNT_IF(cod_setor_atividade_organizacao IS NOT NULL),
        'tp_equipe_vendas', COUNT_IF(tp_equipe_vendas IS NULL), COUNT_IF(tp_equipe_vendas IS NOT NULL),
        'cod_emissor_ordem', COUNT_IF(cod_emissor_ordem IS NULL), COUNT_IF(cod_emissor_ordem IS NOT NULL),
        'dh_atualizacao', COUNT_IF(dh_atualizacao IS NULL), COUNT_IF(dh_atualizacao IS NOT NULL),
        'dh_carga', COUNT_IF(dh_carga IS NULL), COUNT_IF(dh_carga IS NOT NULL)
    ) AS (campo, nulos, preenchidos)
    FROM base
)
SELECT
    campo,
    nulos,
    preenchidos,
    ROUND(100.0 * preenchidos / NULLIF(nulos + preenchidos, 0), 2)
        AS percentual_preenchido
FROM perfil
ORDER BY percentual_preenchido, campo;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 9. Distribuições principais

-- COMMAND ----------

SELECT cod_centro, COUNT(*) AS remessas
FROM vl06if_dl
GROUP BY cod_centro
ORDER BY remessas DESC;

-- COMMAND ----------

SELECT
    cod_fornecedor,
    nm_fornecedor,
    COUNT(*) AS remessas
FROM vl06if_dl
GROUP BY cod_fornecedor, nm_fornecedor
ORDER BY remessas DESC
LIMIT 100;

-- COMMAND ----------

SELECT
    tp_remessa,
    tp_ctg_item_remessa,
    st_movimento_mercadorias_item,
    st_movimento_mercadorias_todos_itens,
    COUNT(*) AS remessas
FROM vl06if_dl
GROUP BY
    tp_remessa,
    tp_ctg_item_remessa,
    st_movimento_mercadorias_item,
    st_movimento_mercadorias_todos_itens
ORDER BY remessas DESC;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 10. Datas, freshness e faixas numéricas

-- COMMAND ----------

SELECT
    MIN(dt_criacao) AS min_dt_criacao,
    MAX(dt_criacao) AS max_dt_criacao,
    MIN(dt_remessa) AS min_dt_remessa,
    MAX(dt_remessa) AS max_dt_remessa,
    MIN(dt_movimentacao_mercadoria_real) AS min_dt_movimento_real,
    MAX(dt_movimentacao_mercadoria_real) AS max_dt_movimento_real,
    MIN(dt_planejada_movimento_mercadoria) AS min_dt_movimento_planejado,
    MAX(dt_planejada_movimento_mercadoria) AS max_dt_movimento_planejado,
    MIN(dt_disponibilizacao_material) AS min_dt_disponibilizacao,
    MAX(dt_disponibilizacao_material) AS max_dt_disponibilizacao,
    MIN(dh_atualizacao) AS min_dh_atualizacao,
    MAX(dh_atualizacao) AS max_dh_atualizacao,
    MIN(dh_carga) AS min_dh_carga,
    MAX(dh_carga) AS max_dh_carga
FROM vl06if_dl;

-- COMMAND ----------

SELECT
    MIN(qt_fornecida_fato_umv) AS min_quantidade,
    MAX(qt_fornecida_fato_umv) AS max_quantidade,
    AVG(qt_fornecida_fato_umv) AS media_quantidade,
    MIN(qt_peso_bruto_total) AS min_peso_kg,
    MAX(qt_peso_bruto_total) AS max_peso_kg,
    AVG(qt_peso_bruto_total) AS media_peso_kg,
    MIN(qt_itens_relevantes) AS min_itens,
    MAX(qt_itens_relevantes) AS max_itens,
    AVG(qt_itens_relevantes) AS media_itens
FROM vl06if_dl;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 11. Exportações finais
-- MAGIC
-- MAGIC Exporte a primeira consulta para a comparação externa com o SAP. Exporte a segunda como lista auditável das ausências.

-- COMMAND ----------

SELECT
    cod_centro,
    num_remessa,
    cod_material,
    num_item_remessa,
    nm_material_cliente,
    dt_criacao,
    cod_fornecedor,
    nm_fornecedor,
    cod_deposito,
    sg_unidade_medida_basica,
    qt_fornecida_fato_umv,
    num_pedido_compra,
    nm_inverted,
    qt_total_volumes_remessa,
    qt_itens_relevantes,
    cod_local_expedicao_ponto_recebimento,
    num_conhecimento_transporte,
    qt_peso_bruto_total,
    st_verificacao_credito_global,
    ind_correcao_re_avancada,
    qt_contador,
    ind_item_devolucao,
    tp_remessa,
    tp_ctg_item_remessa,
    tp_movimento_administracao_estoques,
    st_movimento_mercadorias_item,
    dt_remessa,
    dt_movimentacao_mercadoria_real,
    dt_planejada_movimento_mercadoria,
    dt_disponibilizacao_material,
    num_item_pedido_compra,
    num_referencia,
    st_movimento_mercadorias_todos_itens,
    cod_zonas_disponibilizacao_sistema_deposito,
    cod_organizacao_vendas,
    cod_canal_distribuicao,
    cod_setor_atividade_organizacao,
    tp_equipe_vendas,
    cod_emissor_ordem,
    dh_atualizacao,
    dh_carga
FROM vl06if_dl
ORDER BY num_remessa;

-- COMMAND ----------

SELECT *
FROM vl06if_remessas_ausentes
ORDER BY num_remessa_sap;

-- COMMAND ----------

-- MAGIC %md
-- MAGIC ## 12. Resumo executivo

-- COMMAND ----------

WITH dl_agrupado AS (
    SELECT chave_remessa, COUNT(*) AS qtd_linhas
    FROM vl06if_dl
    GROUP BY chave_remessa
), cobertura AS (
    SELECT
        COUNT(*) AS remessas_sap,
        COUNT_IF(dl.chave_remessa IS NOT NULL) AS encontradas,
        COUNT_IF(dl.chave_remessa IS NULL) AS ausentes,
        SUM(COALESCE(dl.qtd_linhas, 0)) AS linhas_dl,
        COUNT_IF(COALESCE(dl.qtd_linhas, 0) > 1) AS chaves_repetidas
    FROM vl06if_remessas_sap sap
    LEFT JOIN dl_agrupado dl
        ON sap.chave_remessa = dl.chave_remessa
)
SELECT
    remessas_sap,
    encontradas,
    ausentes,
    linhas_dl,
    chaves_repetidas,
    ROUND(100.0 * encontradas / remessas_sap, 2) AS cobertura_percentual,
    (SELECT SUM(GREATEST(COALESCE(qt_itens_relevantes, 0) - 1, 0)) FROM vl06if_dl)
        AS itens_adicionais_nao_representados_como_linha,
    (SELECT MAX(dh_carga) FROM vl06if_dl) AS ultima_carga_no_recorte,
    (SELECT MAX(dh_atualizacao) FROM vl06if_dl) AS ultima_atualizacao_no_recorte
FROM cobertura;